krpano.action:
var k = krpano;
if (k.get("webvr.isenabled") != true) return;
if (k.get("hotspot[react_vr_bottombar_panel].visible") != true) return;
var sw = Number(k.get("stagewidth")) || 0;
var sh = Number(k.get("stageheight")) || 0;
if (sw < 8 || sh < 8) return;
if (typeof k.screentosphere != "function") return;
var baseY = sh - 14;
var stL = k.screentosphere(sw * 0.25, baseY);
var stR = k.screentosphere(sw * 0.75, baseY);
var baseAth, atv;
if (stL && stR && !isNaN(stL.x) && !isNaN(stR.x) && !isNaN(stL.y) && !isNaN(stR.y)) {
	baseAth = (stL.x + stR.x) * 0.5 + 0;
	atv = (stL.y + stR.y) * 0.5;
} else {
	var stRef = k.screentosphere(sw * 0.5, baseY);
	if (!stRef) return;
	baseAth = stRef.x + 0;
	atv = stRef.y;
}
function placeHS(name) {
	var h = k.get("hotspot[" + name + "]");
	if (h) { h.ath = baseAth; h.atv = atv; }
}
placeHS("react_vr_bottombar_panel");
placeHS("react_vr_nav_0");
placeHS("react_vr_nav_1");
placeHS("react_vr_nav_2");
placeHS("react_vr_nav_3");
placeHS("react_vr_nav_4");
placeHS("react_vr_nav_5");
placeHS("react_vr_nav_6");
placeHS("react_vr_nav_7");
placeHS("react_vr_nav_8");
placeHS("react_vr_nav_9");

set(hotspot[react_vr_nav_0].visible, get(v));
set(hotspot[react_vr_nav_0].enabled, get(v));
set(hotspot[react_vr_nav_1].visible, get(v));
set(hotspot[react_vr_nav_1].enabled, get(v));
set(hotspot[react_vr_nav_2].visible, get(v));
set(hotspot[react_vr_nav_2].enabled, get(v));
set(hotspot[react_vr_nav_3].visible, get(v));
set(hotspot[react_vr_nav_3].enabled, get(v));
set(hotspot[react_vr_nav_4].visible, get(v));
set(hotspot[react_vr_nav_4].enabled, get(v));
set(hotspot[react_vr_nav_5].visible, get(v));
set(hotspot[react_vr_nav_5].enabled, get(v));
set(hotspot[react_vr_nav_6].visible, get(v));
set(hotspot[react_vr_nav_6].enabled, get(v));
set(hotspot[react_vr_nav_7].visible, get(v));
set(hotspot[react_vr_nav_7].enabled, get(v));
set(hotspot[react_vr_nav_8].visible, get(v));
set(hotspot[react_vr_nav_8].enabled, get(v));
set(hotspot[react_vr_nav_9].visible, get(v));
set(hotspot[react_vr_nav_9].enabled, get(v));

if(v == 1,
	set(hotspot[react_vr_bottombar_panel].visible, true);
	set(hotspot[react_vr_bottombar_panel].enabled, true);
	react_vr_navbar_set_visibility_children(1);
	react_vr_followbar_sync();
	delayedcall(0.2, react_vr_followbar_sync());
	delayedcall(0.5, react_vr_followbar_sync());
  ,
	set(hotspot[react_vr_bottombar_panel].visible, false);
	set(hotspot[react_vr_bottombar_panel].enabled, false);
	react_vr_navbar_set_visibility_children(0);
);
